"""Checks for notebooks/analysis.ipynb, which is generated by scripts/make_notebook.py.

The notebook is not executed here (that needs a Jupyter kernel and takes time). Instead these
tests make sure the committed notebook matches the generator and was saved after a clean run.
"""
from __future__ import annotations

import nbformat
import pytest

import make_notebook

NOTEBOOK = make_notebook.NOTEBOOK


@pytest.fixture(scope="module")
def saved():
    return nbformat.read(NOTEBOOK, as_version=4)


def test_notebook_matches_generator(saved) -> None:
    """If this fails, run scripts/make_notebook.py and re-execute the notebook."""
    insights = make_notebook.INSIGHTS.read_text(encoding="utf-8").strip()
    expected = make_notebook.build_notebook(insights)
    assert [c.source for c in saved.cells] == [c.source for c in expected.cells]


def test_notebook_was_executed_without_errors(saved) -> None:
    code_cells = [c for c in saved.cells if c.cell_type == "code"]
    assert all(c.execution_count for c in code_cells), "notebook was saved without running every cell"
    errors = [o for c in code_cells for o in c.outputs if o.output_type == "error"]
    assert errors == []


def test_every_chart_rendered(saved) -> None:
    images = [o for c in saved.cells if c.cell_type == "code" for o in c.outputs if "image/png" in o.get("data", {})]
    assert len(images) == 5


def test_insights_are_written_and_short(saved) -> None:
    """PROJECT_PLAN M5: a key-insights section in plain language, 5 bullets max."""
    text = make_notebook.INSIGHTS.read_text(encoding="utf-8")
    bullets = [line for line in text.splitlines() if line[:2].rstrip(".").isdigit() or line.startswith("- ")]
    assert 1 <= len(bullets) <= 5
    assert not any("INSIGHTS_PLACEHOLDER" in c.source for c in saved.cells)


def test_notebook_only_uses_existing_queries() -> None:
    from run_analysis import load_queries

    names = load_queries()
    used = {name for _, src in make_notebook.CELLS for name in names if f'q("{name}")' in src}
    called = sum(src.count('q("') for _, src in make_notebook.CELLS)
    assert len(used) == called  # every q("...") call names a real query
